Algorithm Cronometro
  Define segundos As Integer <- 3725;
  Define horas As Integer <- segundos Div 3600;
  Define minutos As Integer <- segundos Mod 3600 Div 60;
  Write horas, " h ", minutos, " min ", segundos Mod 60, " s";
EndAlgorithm
